            {activeTab !== 'dashboard' && (() => {
              const item = MENU_ITEMS.find(m => !m.isSeparator && m.id === activeTab) as { label?: string } | undefined;
              if (!item?.label) return null;
              const Art = TAB_ART[activeTab] ?? SpotOrders;
