              <div>
                <label className="block text-[0.55rem] font-black text-ds-ink3 uppercase tracking-widest mb-1.5">Email</label>
                <input
                  type="email"
                  value={newUser.email}
                  onChange={e => setNewUser({ ...newUser, email: e.target.value })}
