  const [loading, setLoading]   = useState(true);
  const [filter, setFilter]     = useState<FilterTab>('ALL');
  const [search, setSearch]     = useState('');
  const [saving, setSaving]     = useState<Set<string>>(new Set());
  const [bulkSaving, setBulkSaving] = useState(false);

  // ── Load data ──────────────────────────────────────────────────────────────

  const loadData = useCallback(async () => {
    setLoading(true);
    const { data, error } = await callGateway('admin_list_commissions', { limit: 1000 });

    if (error) {
      console.error('CommissionLedger load:', error);
      setLoading(false);
      return;
    }

    const mapped: CommissionRow[] = ((data ?? []) as any[]).map((row: any) => ({
      id:                row.id,
      agent_id:          row.agent_id,
      client_name:       row.client_name,
      product_type:      row.product_type,
      premium_amount:    row.premium_amount,
      commission_amount: row.commission_amount,
      discount_rate:     row.discount_rate,
      coin_reward:       row.coin_reward,
      order_number:      row.order_number,
      status:            row.status as CommissionStatus,
      created_at:        row.created_at,
      paid_at:           row.paid_at,
      agentName:         row.sp_users?.name ?? 'Agent',
    }));

    setRows(mapped);
    setLoading(false);
  }, []);

  useEffect(() => {
    loadData();
  }, [loadData]);

  // ── Actions ────────────────────────────────────────────────────────────────

  const payCommission = async (id: string) => {
    setSaving(prev => new Set(prev).add(id));
    const { error } = await callGateway('admin_update_commission', { commission_id: id, status: 'PAID' });
    if (!error) {
      setRows(prev =>
        prev.map(r =>
          r.id === id ? { ...r, status: 'PAID', paid_at: new Date().toISOString() } : r
        )
      );
    }
    setSaving(prev => {
      const next = new Set(prev);
      next.delete(id);
      return next;
    });
  };

  const cancelCommission = async (id: string) => {
    setSaving(prev => new Set(prev).add(id));
    const { error } = await callGateway('admin_update_commission', { commission_id: id, status: 'CANCELLED' });
    if (!error) {
      setRows(prev =>
        prev.map(r => (r.id === id ? { ...r, status: 'CANCELLED' } : r))
      );
    }
    setSaving(prev => {
      const next = new Set(prev);
      next.delete(id);
      return next;
    });
  };

  const payAllPending = async () => {
    const pendingIds = rows
      .filter(r => r.status === 'PENDING')
      .map(r => r.id);
    if (pendingIds.length === 0) return;
    setBulkSaving(true);
    const now = new Date().toISOString();
    const { error } = await supabase
      .from('sp_commissions')
      .update({ status: 'PAID', paid_at: now })
      .in('id', pendingIds);
    if (!error) {
      setRows(prev =>
        prev.map(r =>
          r.status === 'PENDING' ? { ...r, status: 'PAID', paid_at: now } : r
        )
      );
    }
    setBulkSaving(false);
  };

  // ── Derived state ──────────────────────────────────────────────────────────

  const filtered = rows.filter(r => {
    const matchStatus = filter === 'ALL' || r.status === filter;
    if (!matchStatus) return false;
    if (!search.trim()) return true;
    const q = search.toLowerCase();
    return (
      r.agentName.toLowerCase().includes(q) ||
      r.client_name.toLowerCase().includes(q) ||
      (r.order_number ?? '').toLowerCase().includes(q)
    );
  });

  const pendingCount  = rows.filter(r => r.status === 'PENDING').length;
  const totalAmount   = filtered.reduce((s, r) => s + r.commission_amount, 0);

  const TABS: FilterTab[] = ['ALL', 'PENDING', 'PAID', 'CANCELLED'];

  return (
    <div className="space-y-6 animate-fade-in bg-ds-card2 text-ds-ink">
      {/* ── Header ── */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h2 className="text-2xl font-bold tracking-tight text-ds-ink">
            Komisi <span className="text-ds-green">Ledger</span>
          </h2>
          <p className="text-xs uppercase tracking-wide text-ds-ink3 font-semibold mt-1">
            Manajemen komisi agen
          </p>
        </div>
        <button
          onClick={payAllPending}
          disabled={bulkSaving || pendingCount === 0}
          className={`h-10 px-4 rounded-xl text-sm font-semibold transition-all active:scale-95 ${
            pendingCount === 0
              ? 'bg-gray-100 text-ds-ink3 cursor-not-allowed'
              : 'bg-emerald-500 text-white hover:bg-emerald-600'
          }`}
        >
          {bulkSaving ? 'Memproses…' : `Bayar Semua PENDING (${pendingCount})`}
        </button>
      </div>

      {/* ── Filter tabs + search ── */}
      <div className="flex flex-col sm:flex-row items-start sm:items-center gap-3">
        <div className="flex gap-1 bg-white p-1 rounded-2xl border border-ds-border shadow-sm flex-wrap">
          {TABS.map(tab => {
            const count = tab === 'ALL'
              ? rows.length
              : rows.filter(r => r.status === tab).length;
            return (
              <button
                key={tab}
                onClick={() => setFilter(tab)}
                className={`px-4 py-2 rounded-xl text-xs font-semibold transition-all ${
                  filter === tab
                    ? 'bg-emerald-500 text-white shadow-sm'
                    : 'text-ds-ink3 hover:bg-ds-card2'
                }`}
              >
                {tab === 'ALL' ? 'Semua' : STATUS_LABEL[tab as CommissionStatus]}{' '}
                <span className="opacity-60">({count})</span>
              </button>
            );
          })}
        </div>
        <div className="relative flex-1 min-w-[200px]">
          <Search size={14} className="absolute left-3 top-1/2 -translate-y-1/2 text-ds-ink3" />
          <input
            type="text"
            placeholder="Cari agen / klien…"
            value={search}
            onChange={e => setSearch(e.target.value)}
            className="w-full h-10 pl-9 pr-3 bg-white border border-ds-border rounded-xl text-sm text-ds-ink outline-none focus:ring-2 focus:ring-emerald-500/30 focus:border-emerald-500 transition-colors placeholder:text-ds-ink3"
          />
        </div>
      </div>

      {/* ── Summary bar ── */}
      <div className="bg-white border border-ds-border shadow-sm rounded-2xl px-6 py-3 flex items-center justify-between flex-wrap gap-2">
        <p className="text-xs text-ds-ink3 font-semibold uppercase tracking-wide">
          Menampilkan{' '}
          <span className="text-ds-ink font-bold">{filtered.length}</span>{' '}
          dari {rows.length} komisi
        </p>
        <p className="text-xs text-ds-ink3 font-semibold uppercase tracking-wide">
          Total:{' '}
          <span className="text-ds-green font-bold font-mono">{formatIDR(totalAmount)}</span>
        </p>
      </div>

      {/* ── Content ── */}
      {loading ? (
        <div className="flex justify-center py-24">
          <div className="w-10 h-10 rounded-full border-4 border-emerald-500/20 border-t-emerald-500 animate-spin" />
        </div>
      ) : filtered.length === 0 ? (
        <div className="bg-white border border-ds-border shadow-sm rounded-2xl text-center py-16 text-ds-ink3 font-medium text-sm">
          Tidak ada data komisi.
        </div>
      ) : (
        <div className="space-y-2">
          {filtered.map(row => {
            const isBusy = saving.has(row.id);
            return (
              <div
                key={row.id}
                className="bg-white border border-ds-border shadow-sm rounded-2xl px-6 py-4 hover:bg-ds-card2 transition-colors"
              >
                <div className="flex flex-col md:flex-row md:items-center gap-3">
                  {/* ── Left: identity ── */}
                  <div className="flex-1 min-w-0 space-y-1">
                    <div className="flex items-center gap-2 flex-wrap">
                      <p className="text-sm font-bold text-ds-ink">{row.agentName}</p>
                      <span
                        className={`px-2.5 py-0.5 rounded-full text-xs font-semibold ${STATUS_BADGE[row.status]}`}
                      >
                        {STATUS_LABEL[row.status]}
                      </span>
                    </div>
                    <p className="text-[10px] text-ds-ink3 font-semibold">
                      {row.client_name}
                      {row.order_number && (
                        <span className="ml-2 text-ds-ink2 font-mono">{row.order_number}</span>
                      )}
                    </p>
                    <p className="text-[9px] font-black uppercase tracking-widest text-ds-ink2">
                      {row.product_type}
                      {row.discount_rate !== undefined && row.discount_rate !== null && (
                        <span className="ml-2 text-rose-500/60">Diskon {(row.discount_rate * 100).toFixed(0)}%</span>
                      )}
                      {row.paid_at && (
                        <span className="ml-2 text-ds-green/60">Dibayar {fmtDate(row.paid_at)}</span>
                      )}
                      {!row.paid_at && row.created_at && (
                        <span className="ml-2 text-ds-ink2">{fmtDate(row.created_at)}</span>
                      )}
                    </p>
                  </div>

                  {/* ── Middle: amounts ── */}
                  <div className="flex items-center gap-6 text-right flex-shrink-0">
                    <div>
                      <p className="text-[9px] font-black uppercase tracking-widest text-ds-ink2">Premi</p>
                      <p className="text-xs font-mono text-ds-ink">{formatIDR(row.premium_amount)}</p>
                    </div>
                    <div>
                      <p className="text-[9px] font-black uppercase tracking-widest text-ds-ink2">Komisi</p>
                      <p className="text-sm font-black text-amber-400">{formatIDR(row.commission_amount)}</p>
                    </div>
                    {row.coin_reward !== undefined && row.coin_reward !== null && row.coin_reward > 0 && (
                      <div>
                        <p className="text-[9px] font-black uppercase tracking-widest text-ds-ink2">Koin</p>
                        <p className="text-xs font-mono text-emerald-400">
                          {row.coin_reward.toLocaleString('id-ID')}
                        </p>
                      </div>
                    )}
                  </div>

                  {/* ── Right: actions ── */}
                  {row.status === 'PENDING' && (
                    <div className="flex gap-2 flex-shrink-0">
                      <button
                        disabled={isBusy}
                        onClick={() => payCommission(row.id)}
                        className="px-4 py-2 rounded-xl text-[0.6rem] font-black uppercase tracking-widest bg-emerald-500 text-white hover:bg-emerald-600 active:scale-95 transition-all disabled:opacity-40"
                      >
                        {isBusy ? '…' : 'Bayar'}
                      </button>
                      <button
                        disabled={isBusy}
                        onClick={() => cancelCommission(row.id)}
                        className="px-4 py-2 rounded-xl text-[0.6rem] font-black uppercase tracking-widest bg-rose-500/10 text-rose-400 hover:bg-rose-500 hover:text-white active:scale-95 transition-all disabled:opacity-40"
                      >
                        {isBusy ? '…' : 'Batalkan'}
                      </button>
                    </div>
                  )}
                </div>
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
};

export default CommissionLedger;

import React, { useState, useEffect, useMemo } from 'react';
import {
  FileText, Image, User, Eye, Filter, Search, FileImage, Shield,
} from 'lucide-react';
import { getAllOrders, callGateway, supabase, resolveDocumentUrl } from '../../services/supabaseService';

// ─── Types ────────────────────────────────────────────────────────────────────

type DocType = 'policy' | 'vehicle' | 'ktp' | 'claim';

interface DocItem {
  id: string;
  type: DocType;
  url: string;
  ownerName: string;
  ref: string;       // order_number / claim_number / email
  status: string;
  date: string;
  isPdf?: boolean;
}

type FilterTab = 'all' | DocType;

const TYPE_META: Record<DocType, { label: string; badgeCls: string; icon: React.ElementType }> = {
  policy:  { label: 'Policy Doc',      badgeCls: 'bg-blue-500/15 text-blue-400 border-blue-500/20',   icon: FileText  },
  vehicle: { label: 'Vehicle Image',   badgeCls: 'bg-green-500/15 text-green-400 border-green-500/20', icon: Image     },
  ktp:     { label: 'KTP',             badgeCls: 'bg-amber-500/15 text-amber-400 border-amber-500/20', icon: User      },
  claim:   { label: 'Claim Photo',     badgeCls: 'bg-rose-500/15 text-rose-400 border-rose-500/20',    icon: Shield    },
};

const FILTER_TABS: { id: FilterTab; label: string }[] = [
  { id: 'all',     label: 'Semua'          },
  { id: 'policy',  label: 'Policy Docs'    },
  { id: 'vehicle', label: 'Vehicle Images' },
  { id: 'ktp',     label: 'KTP'            },
  { id: 'claim',   label: 'Claim Photos'   },
];

// ─── Skeleton card ────────────────────────────────────────────────────────────

const SkeletonCard = () => (
  <div className="rounded-2xl border border-ds-border bg-ds-card2 overflow-hidden animate-pulse">
    <div className="h-40 bg-ds-card2" />
    <div className="p-4 space-y-2">
      <div className="h-3 bg-ds-card2 rounded w-2/3" />
      <div className="h-2.5 bg-ds-card2 rounded w-1/2" />
      <div className="h-2.5 bg-ds-card2 rounded w-1/3" />
    </div>
  </div>
);

// ─── Document card ────────────────────────────────────────────────────────────

const DocCard: React.FC<{ doc: DocItem }> = ({ doc }) => {
  const meta = TYPE_META[doc.type];
  const Icon = meta.icon;
  const isBase64 = doc.url.startsWith('data:image');
  const isImageUrl = !doc.isPdf && !isBase64 &&
    /\.(jpe?g|png|webp|gif|heic|bmp|svg)(\?|$)/i.test(doc.url);
  const showThumb = isBase64 || isImageUrl;

  return (
    <div className="group rounded-2xl border border-ds-border bg-ds-card2 hover:border-ds-border hover:bg-ds-card2 overflow-hidden transition-all flex flex-col">
      {/* Thumbnail / icon area */}
      <div className="h-40 bg-ds-card2 flex items-center justify-center relative overflow-hidden">
        {showThumb ? (
          <img
            src={doc.url}
            alt={meta.label}
            className="w-full h-full object-cover"
            loading="lazy"
            onError={e => { (e.currentTarget as HTMLImageElement).style.display = 'none'; }}
          />
        ) : (
          <div className="flex flex-col items-center gap-2 opacity-40">
            {doc.isPdf ? <FileText size={36} className="text-blue-400" /> : <FileImage size={36} />}
            <span className="text-[0.55rem] font-bold uppercase tracking-widest text-ds-ink3">
              {doc.isPdf ? 'PDF' : 'Document'}
            </span>
          </div>
        )}
        {/* Type badge overlay */}
        <span className={`absolute top-2 left-2 text-[0.5rem] font-black uppercase tracking-widest px-2 py-0.5 rounded-full border backdrop-blur-sm ${meta.badgeCls}`}>
          <span className="flex items-center gap-1">
            <Icon size={8} />
            {meta.label}
          </span>
        </span>
      </div>

      {/* Meta */}
      <div className="p-4 flex flex-col gap-1 flex-1">
        <p className="text-xs font-black text-white truncate">{doc.ownerName}</p>
        <p className="text-[0.6rem] font-medium text-ds-ink3 truncate">{doc.ref}</p>
        <div className="flex items-center justify-between mt-1">
          <span className="text-[0.5rem] font-bold uppercase tracking-widest text-ds-ink2">
            {doc.date ? new Date(doc.date).toLocaleDateString('id-ID', { day: 'numeric', month: 'short', year: 'numeric' }) : '—'}
          </span>
          <span className={`text-[0.48rem] font-black uppercase tracking-widest px-1.5 py-0.5 rounded-full ${
            doc.status === 'ISSUED' || doc.status === 'APPROVED'
              ? 'bg-emerald-500/10 text-emerald-400'
              : doc.status === 'REJECTED'
              ? 'bg-rose-500/10 text-rose-400'
              : 'bg-amber-500/10 text-amber-400'
          }`}>
            {doc.status}
          </span>
        </div>
        {/* Open button */}
        <a
          href={doc.url}
          target="_blank"
          rel="noopener noreferrer"
          className="mt-3 flex items-center justify-center gap-1.5 py-2 rounded-xl bg-ds-card2 hover:bg-ds-card2 border border-ds-border hover:border-ds-border transition-all text-[0.6rem] font-black uppercase tracking-widest text-ds-ink2 hover:text-white"
        >
          <Eye size={11} /> Buka
        </a>
      </div>
    </div>
  );
};

// ─── Main component ───────────────────────────────────────────────────────────

const DocumentsAdminView: React.FC = () => {
  const [docs, setDocs]       = useState<DocItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [filter, setFilter]   = useState<FilterTab>('all');
  const [search, setSearch]   = useState('');

  // ── Fetch all document sources in parallel ─────────────────────────────────
  useEffect(() => {
    let cancelled = false;

    const fetchDocs = async () => {
      setLoading(true);

      const [ordersResult, usersResult, claimsResult] = await Promise.allSettled([
        getAllOrders(),
        callGateway('admin_list_users', {}),
        supabase.from('sp_claims').select('*').order('created_at', { ascending: false }),
      ]);

      if (cancelled) return;

      const collected: DocItem[] = [];

      // ── Orders: policy docs + vehicle images + STNK/survey_photos ──────────
      const orders = ordersResult.status === 'fulfilled' ? ordersResult.value : [];
      for (const o of orders) {
        const base = {
          ownerName: o.client_name,
          ref: o.order_number ?? o.id,
          status: o.status,
          date: o.created_at ?? '',
        };

        if (o.policy_document_url) {
          collected.push({
            id: `order-policy-${o.id}`,
            type: 'policy',
            url: o.policy_document_url,
            isPdf: true,
            ...base,
          });
        }

        if (o.vehicle_image_url) {
          collected.push({
            id: `order-vehicle-${o.id}`,
            type: 'vehicle',
            url: o.vehicle_image_url,
            ...base,
          });
        }

        // vehicle_details may have stnk_url or survey_photos
        if (o.vehicle_details && typeof o.vehicle_details === 'object') {
          const vd = o.vehicle_details as Record<string, any>;
          if (vd.stnk_url && typeof vd.stnk_url === 'string') {
            collected.push({
              id: `order-stnk-${o.id}`,
              type: 'vehicle',
              url: vd.stnk_url,
              ...base,
            });
          }
          if (Array.isArray(vd.survey_photos)) {
            vd.survey_photos.forEach((url: string, idx: number) => {
              if (url) {
                collected.push({
                  id: `order-survey-${o.id}-${idx}`,
                  type: 'vehicle',
                  url,
                  ...base,
                });
              }
            });
          }
        }
      }

      // ── Users: KTP + profile photos ────────────────────────────────────────
      if (usersResult.status === 'fulfilled') {
        const usersData = usersResult.value;
        const users: any[] = Array.isArray(usersData?.data)
          ? usersData.data
          : Array.isArray(usersData)
          ? usersData
          : [];

        for (const u of users) {
          if (u.ktp_document_url) {
            collected.push({
              id: `user-ktp-${u.id ?? u.email}`,
              type: 'ktp',
              url: u.ktp_document_url,
              ownerName: u.name ?? u.email ?? 'Unknown',
              ref: u.email ?? u.id ?? '',
              status: u.role ?? 'USER',
              date: u.created_at ?? '',
            });
          }
        }
      }

      // ── Claims: photos array ───────────────────────────────────────────────
      if (claimsResult.status === 'fulfilled' && !claimsResult.value.error) {
        const claims: any[] = claimsResult.value.data ?? [];
        for (const c of claims) {
          const photos: string[] = Array.isArray(c.photos) ? c.photos : [];
          photos.forEach((photo, idx) => {
            if (photo) {
              collected.push({
                id: `claim-photo-${c.id}-${idx}`,
                type: 'claim',
                url: photo,
                ownerName: c.claimant_name ?? 'Unknown',
                ref: c.claim_number ?? c.id,
                status: c.status ?? 'SUBMITTED',
                date: c.created_at ?? '',
              });
            }
          });
        }
      }

      // policy/ktp docs live in private buckets — swap for signed URLs before
      // rendering; still-public buckets (vehicle/claim photos) pass through as-is.
      const resolved = await Promise.all(
        collected.map(async d => ({ ...d, url: (await resolveDocumentUrl(d.url)) ?? d.url }))
      );

      if (!cancelled) {
        setDocs(resolved);
        setLoading(false);
      }
    };

    fetchDocs();
    return () => { cancelled = true; };
  }, []);

  // ── Filtered + searched docs ───────────────────────────────────────────────
  const visible = useMemo(() => {
    let result = filter === 'all' ? docs : docs.filter(d => d.type === filter);
    if (search.trim()) {
      const q = search.toLowerCase();
      result = result.filter(
        d => d.ownerName.toLowerCase().includes(q) || d.ref.toLowerCase().includes(q),
      );
    }
    return result;
  }, [docs, filter, search]);

  // ── Stats ──────────────────────────────────────────────────────────────────
  const counts = useMemo(() => ({
    policy:  docs.filter(d => d.type === 'policy').length,
    vehicle: docs.filter(d => d.type === 'vehicle').length,
    ktp:     docs.filter(d => d.type === 'ktp').length,
    claim:   docs.filter(d => d.type === 'claim').length,
  }), [docs]);

  return (
    <div className="space-y-6">
      {/* Header */}
      <div>
        <div className="flex items-center gap-2 mb-1">
          <FileImage size={14} className="text-ds-green" />
          <p className="text-[0.55rem] font-black uppercase tracking-[0.35em] text-ds-green">Galeri Dokumen</p>
        </div>
        <h2 className="text-3xl font-black tracking-tight leading-none text-white">
          Document Gallery
        </h2>

        {/* Stats chips */}
        {!loading && (
          <div className="flex flex-wrap gap-2 mt-3">
            {[
              { label: 'Policy Docs',     count: counts.policy,  cls: 'bg-blue-500/10 text-blue-400 border-blue-500/20'   },
              { label: 'Vehicle Images',  count: counts.vehicle, cls: 'bg-green-500/10 text-green-400 border-green-500/20' },
              { label: 'KTP',             count: counts.ktp,     cls: 'bg-amber-500/10 text-amber-400 border-amber-500/20' },
              { label: 'Claim Photos',    count: counts.claim,   cls: 'bg-rose-500/10 text-rose-400 border-rose-500/20'    },
            ].map(chip => (
              <span key={chip.label} className={`text-[0.55rem] font-black uppercase tracking-widest px-3 py-1 rounded-full border ${chip.cls}`}>
                {chip.count} {chip.label}
              </span>
            ))}
          </div>
        )}
      </div>

      {/* Filter bar */}
      <div className="flex flex-col sm:flex-row gap-3 items-start sm:items-center">
        <div className="flex items-center gap-1 p-1 rounded-2xl bg-ds-card2 border border-ds-border flex-wrap">
          <Filter size={12} className="ml-2 text-ds-ink2 flex-shrink-0" />
          {FILTER_TABS.map(tab => (
            <button
              key={tab.id}
              onClick={() => setFilter(tab.id)}
              className={`px-3 py-1.5 rounded-xl text-[0.6rem] font-black uppercase tracking-widest transition-all ${
                filter === tab.id
                  ? 'bg-emerald-500/10 text-emerald-400 border border-emerald-500/20'
                  : 'text-ds-ink3 hover:text-white'
              }`}
            >
              {tab.label}
            </button>
          ))}
        </div>

        {/* Search */}
        <div className="relative flex-shrink-0">
          <Search size={13} className="absolute left-3 top-1/2 -translate-y-1/2 text-ds-ink3" />
          <input
            type="text"
            value={search}
            onChange={e => setSearch(e.target.value)}
            placeholder="Cari nama / nomor..."
            className="pl-9 pr-4 py-2 rounded-xl bg-ds-card2 border border-ds-border text-xs text-white placeholder-gray-600 outline-none focus:border-emerald-500/40 w-56"
          />
        </div>
      </div>

      {/* Content */}
      {loading ? (
