      prev.map((e) =>
        e.id === id
          ? { ...e, status, reviewer_notes: notes ?? null, reviewed_at: new Date().toISOString() }
          : e,
      ),
    );
    setActionId(null);
    setNotesFor(null);
    setNotesInput('');
